mapper.select:
SELECT p.id, p.owner_id, p.project_name, p.avatar_url, p.announcement, p.category, p.status, COALESCE(brief_stats.brief_count, 0) AS brief_count, COALESCE(script_stats.script_count, 0) AS script_count, COALESCE(video_stats.video_count, 0) AS video_count, p.create_time, p.update_time FROM ai_project p LEFT JOIN ( SELECT project_id, COUNT(*) AS brief_count FROM ( SELECT project_id, id AS brief_id FROM ai_brief WHERE deleted = 0
AND tenant_id = #{tenantId}
UNION SELECT project_id, brief_id FROM ai_project_brief_ref WHERE deleted = 0
AND tenant_id = #{tenantId}
) all_project_briefs GROUP BY project_id ) brief_stats ON brief_stats.project_id = p.id LEFT JOIN ( SELECT project_id, COUNT(*) AS script_count FROM ai_storyboard_script WHERE deleted = 0
AND tenant_id = #{tenantId}
GROUP BY project_id ) script_stats ON script_stats.project_id = p.id LEFT JOIN ( SELECT project_id, COUNT(*) AS video_count FROM ai_video_segment WHERE 1 = 1
AND tenant_id = #{tenantId}
GROUP BY project_id ) video_stats ON video_stats.project_id = p.id WHERE p.deleted = 0
AND p.tenant_id = #{tenantId}
AND ( p.owner_id = #{ownerId} OR EXISTS ( SELECT 1 FROM ai_project_collaborator collaborator WHERE collaborator.project_id = p.id AND collaborator.tenant_id = p.tenant_id AND collaborator.user_id = #{ownerId} AND collaborator.status = 'active' AND collaborator.deleted = 0 ) )
AND p.project_name LIKE CONCAT('%', #{keyword}, '%')
AND p.status = #{status}
ORDER BY p.update_time DESC
